package com.example.user.util;

public final class AppConstants {

    public static final String CORRELATION_ID_HEADER = "X-Correlation-Id";
    public static final String CORRELATION_ID_MDC_KEY = "correlationId";

    /** User ids are UUIDs generated by this service. */
    public static final String ID_REGEX = "^[0-9a-fA-F-]{36}$";
    /** Letters of any language, spaces, apostrophes and hyphens: "Anne-Marie", "O'Brien", "Müller". */
    public static final String NAME_REGEX = "^\\p{L}[\\p{L} '\\-]*$";
    /** E.164 international format: '+', country code, number (8 to 15 digits in total). */
    public static final String PHONE_REGEX = "^\\+[1-9]\\d{7,14}$";

    public static final int DEFAULT_PAGE_SIZE = 20;
    public static final int MAX_PAGE_SIZE = 100;

    private AppConstants() {
    }
}
